function countQuadruplets(nums) {
  const n = nums.length;
  const diffCount = new Map();
  let count = 0;

  for (let b = n - 3; b >= 1; b--) {
    const c = b + 1;
    for (let d = c + 1; d < n; d++) {
      const diff = nums[d] - nums[c];
      diffCount.set(diff, (diffCount.get(diff) ?? 0) + 1);
    }
    for (let a = 0; a < b; a++) {
      count += diffCount.get(nums[a] + nums[b]) ?? 0;
    }
  }
  return count;
}

