function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 4 + Math.floor(rand() * 9);
  // Small value ranges make matching quadruplets common; the widest range uses the full limits.
  const tops = [3, 6, 12, 30, 100];
  const top = tops[Math.floor(rand() * tops.length)];
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
